# Scenario 4: Aliases - different keys, should BOTH appear
# 'userName' and 'name' are different field names, so both should appear
query GetUserWithAliasedFragments($id: ID!) {
  user(id: $id) {
    ...UserAliasedName
    ...UserRealName
  }
}

# Scenario 2: Inline field + fragment with same field
# Inline 'name' + fragment with 'id' - should not duplicate
query GetUserWithInlineAndFragment($id: ID!) {
  user(id: $id) {
    name
    ...UserWithId
  }
}

# Scenario 1: Overlapping fragments - both have 'name' field
# This should NOT produce duplicate 'name' field in the AST
query GetUserWithOverlappingFragments($id: ID!) {
  user(id: $id) {
    ...UserBasic
    ...UserExtended
  }
}

# Scenario 3: Nested fragments with overlapping fields
# UserNestedA and UserNestedB both include UserFullName (which has 'name')
# This should NOT produce duplicate 'name' field in the AST
query GetUsersWithNestedFragments {
  users {
    ...UserNestedA
    ...UserNestedB
  }
}

# Scenario 1: Overlapping fragments - both have 'name' field
fragment UserBasic on User @public {
  id
  name
}

fragment UserExtended on User @public {
  name
  email
}

# Scenario 2: Fragment for inline + fragment test
fragment UserWithId on User @public {
  id
}

# Scenario 3: Nested fragments with overlapping fields
fragment UserFullName on User @public {
  name
}

fragment UserContact on User @public {
  email
}

fragment UserNestedA on User @public {
  ...UserFullName
  role
}

fragment UserNestedB on User @public {
  ...UserFullName
  ...UserContact
}

# Scenario 4: Aliases - different keys, should both appear
fragment UserAliasedName on User @public {
  userName: name
}

fragment UserRealName on User @public {
  name
}
